import { useEffect, useRef } from 'react';
import sceneJson from '../data/heroScene.json';

/**
 * The landing-page hero artwork: Dusk Peaks, rendered live at the framerate in the scene data
 * (20 fps) instead of cycling four baked frames.
 *
 * The layout - palette ramp, ridge silhouettes, star positions, parallax cloud bands, fireflies and the
 * bird flock - comes from `src/data/heroScene.json`, which is generated by the Java tool in
 * `tools/scene-forge`. That tool also renders the same frames offline for review, so neither language
 * holds a private copy of the art direction. Only the drawing rules live here.
 */

type Rgb = [number, number, number];

const toRgb = (color: number[]): Rgb => [color[0], color[1], color[2]];

const SETTINGS = sceneJson.settings;
const W = SETTINGS.width;
const H = SETTINGS.height;
const HORIZON = SETTINGS.horizon;
const FPS = SETTINGS.fps;

/** What the baked base buffer holds at each pixel, so later layers know what they may draw over. */
const SKY = 1;
const WATER = 2;
const LAND = 3;

const PALETTE = {
  skyStops: sceneJson.palette.skyStops.map((stop) => ({ at: stop.at, color: toRgb(stop.color) })),
  sunCore: toRgb(sceneJson.palette.sunCore),
  sunMid: toRgb(sceneJson.palette.sunMid),
  sunOuter: toRgb(sceneJson.palette.sunOuter),
  sunHalo: toRgb(sceneJson.palette.sunHalo),
  moon: toRgb(sceneJson.palette.moon),
  moonHighlight: toRgb(sceneJson.palette.moonHighlight),
  moonHalo: toRgb(sceneJson.palette.moonHalo),
  starWarm: toRgb(sceneJson.palette.starWarm),
  starCool: toRgb(sceneJson.palette.starCool),
  reflectionNear: toRgb(sceneJson.palette.reflectionNear),
  reflectionFar: toRgb(sceneJson.palette.reflectionFar),
  firefly: toRgb(sceneJson.palette.firefly),
  bird: toRgb(sceneJson.palette.bird),
  waterTop: toRgb(sceneJson.palette.waterTop),
  waterBottom: toRgb(sceneJson.palette.waterBottom),
  waterSheen: toRgb(sceneJson.palette.waterSheen),
};

interface Peak {
  x: number;
  height: number;
  spread: number;
}

interface Ridge {
  baseY: number;
  body: Rgb;
  shade: Rgb;
  rim: Rgb;
  peaks: Peak[];
}

const FAR_RIDGE: Ridge = {
  baseY: sceneJson.farRidge.baseY,
  body: toRgb(sceneJson.farRidge.body),
  shade: toRgb(sceneJson.farRidge.shade),
  rim: toRgb(sceneJson.farRidge.rim),
  peaks: sceneJson.farRidge.peaks,
};

const NEAR_RIDGE: Ridge = {
  baseY: sceneJson.nearRidge.baseY,
  body: toRgb(sceneJson.nearRidge.body),
  shade: toRgb(sceneJson.nearRidge.shade),
  rim: toRgb(sceneJson.nearRidge.rim),
  peaks: sceneJson.nearRidge.peaks,
};

const STARS = sceneJson.stars.map((star) => ({
  x: star.x,
  y: star.y,
  phase: star.phase,
  warm: star.warm,
}));

interface Cloud {
  x: number;
  y: number;
  rx: number;
  ry: number;
  speed: number;
}

interface CloudBand {
  color: Rgb;
  topColor: Rgb;
  alpha: number;
  behindRidges: boolean;
  clouds: Cloud[];
}

const CLOUD_BANDS: CloudBand[] = sceneJson.cloudBands.map((band) => ({
  color: toRgb(band.color),
  topColor: toRgb(band.topColor),
  alpha: band.alpha,
  behindRidges: band.behindRidges,
  clouds: band.clouds,
}));

const FIREFLIES = sceneJson.fireflies;
const BIRDS = sceneJson.birds;

function mix(a: Rgb, b: Rgb, t: number): Rgb {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t),
  ];
}

function skyAt(y: number): Rgb {
  const t = Math.max(0, Math.min(1, y / (HORIZON - 1)));
  for (let i = 0; i < PALETTE.skyStops.length - 1; i++) {
    const { at, color } = PALETTE.skyStops[i];
    const next = PALETTE.skyStops[i + 1];
    if (t <= next.at) return mix(color, next.color, (t - at) / (next.at - at));
  }
  return PALETTE.skyStops[PALETTE.skyStops.length - 1].color;
}

/** Ridge line of a peak range at column `x`; `baseY` is where the slope reaches the water. */
function ridgeTop(x: number, peaks: Peak[], baseY: number): number {
  let top = baseY + 1;
  for (const p of peaks) {
    const d = Math.abs(x - p.x);
    if (d > p.spread) continue;
    const t = 1 - d / p.spread;
    const y = baseY - Math.round(p.height * Math.sin((t * Math.PI) / 2) ** 1.35);
    if (y < top) top = y;
  }
  return top;
}

function paintRange(
  buf: Uint8ClampedArray,
  kinds: Uint8Array,
  ridge: Ridge,
  sunX: number,
): void {
  const baseY = Math.round(ridge.baseY);
  const tops: number[] = [];
  for (let x = 0; x < W; x++) tops.push(ridgeTop(x, ridge.peaks, baseY));
  for (let x = 0; x < W; x++) {
    const top = tops[x];
    const slope = (tops[Math.min(W - 1, x + 1)] ?? top) - (tops[Math.max(0, x - 1)] ?? top);
    const lit = x < sunX ? slope < -0.15 : slope > 0.15;
    for (let y = Math.max(0, top); y < baseY && y < H; y++) {
      const depth = (y - top) / Math.max(1, baseY - top);
      let color = mix(ridge.shade, ridge.body, Math.min(1, depth * 1.6));
      if (y === top) color = ridge.rim;
      else if (y === top + 1) color = mix(ridge.rim, color, 0.55);
      else if (lit) color = mix(color, ridge.rim, 0.18);
      const i = (y * W + x) * 4;
      buf[i] = color[0];
      buf[i + 1] = color[1];
      buf[i + 2] = color[2];
      buf[i + 3] = 255;
      kinds[y * W + x] = LAND;
    }
  }
}

function buildBase(): { pixels: Uint8ClampedArray; kinds: Uint8Array } {
  const pixels = new Uint8ClampedArray(W * H * 4);
  const kinds = new Uint8Array(W * H);

  for (let y = 0; y < H; y++) {
    const isSky = y < HORIZON;
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4;
      let color: Rgb;
      if (isSky) {
        color = skyAt(y);
      } else {
        // Still water, warmer just below the horizon.
        const depth = (y - HORIZON) / Math.max(1, H - HORIZON - 1);
        color = mix(PALETTE.waterTop, PALETTE.waterBottom, depth);
        const wave = Math.sin(x * 0.42 + y * 1.9) * 0.5 + 0.5;
        color = mix(color, PALETTE.waterSheen, wave * 0.2 * (1 - depth));
      }
      pixels[i] = color[0];
      pixels[i + 1] = color[1];
      pixels[i + 2] = color[2];
      pixels[i + 3] = 255;
      kinds[y * W + x] = isSky ? SKY : WATER;
    }
  }

  paintRange(pixels, kinds, FAR_RIDGE, 40);
  paintRange(pixels, kinds, NEAR_RIDGE, 40);

  return { pixels, kinds };
}

function blend(buf: Uint8ClampedArray, x: number, y: number, color: Rgb, alpha: number): void {
  if (x < 0 || y < 0 || x >= W || y >= H || alpha <= 0) return;
  const a = Math.min(1, alpha);
  const i = (y * W + x) * 4;
  buf[i] = Math.round(buf[i] + (color[0] - buf[i]) * a);
  buf[i + 1] = Math.round(buf[i + 1] + (color[1] - buf[i + 1]) * a);
  buf[i + 2] = Math.round(buf[i + 2] + (color[2] - buf[i + 2]) * a);
}

function disc(buf: Uint8ClampedArray, kinds: Uint8Array, cx: number, cy: number, r: number, color: Rgb, alpha: number): void {
  for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y++) {
    for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if ((x - cx) ** 2 + (y - cy) ** 2 > r * r) continue;
      // Celestial bodies sit behind the ridge lines.
      if (kinds[y * W + x] !== SKY) continue;
      blend(buf, x, y, color, alpha);
    }
  }
}

function halo(buf: Uint8ClampedArray, kinds: Uint8Array, cx: number, cy: number, r: number, color: Rgb, strength: number): void {
  for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y++) {
    for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if (kinds[y * W + x] !== SKY) continue;
      const d = Math.hypot(x - cx, y - cy) / r;
      if (d >= 1) continue;
      blend(buf, x, y, color, (1 - d) ** 2 * strength);
    }
  }
}

function cloudBand(buf: Uint8ClampedArray, kinds: Uint8Array, band: CloudBand, t: number): void {
  for (const c of band.clouds) {
    const span = W + c.rx * 2;
    const cx = (((c.x + (t / 1000) * c.speed) % span) + span) % span - c.rx;
    for (let y = Math.floor(c.y - c.ry); y <= Math.ceil(c.y + c.ry); y++) {
      for (let x = Math.floor(cx - c.rx); x <= Math.ceil(cx + c.rx); x++) {
        const sx = ((x % W) + W) % W;
        if (y < 0 || y >= H) continue;
        if (band.behindRidges && kinds[y * W + sx] !== SKY) continue;
        const nx = (x - cx) / c.rx;
        const ny = (y - c.y) / c.ry;
        const d = nx * nx + ny * ny;
        if (d > 1) continue;
        blend(buf, sx, y, ny < -0.25 ? band.topColor : band.color, band.alpha * (1 - d * 0.55));
      }
    }
  }
}

function birds(buf: Uint8ClampedArray, kinds: Uint8Array, t: number): void {
  for (const b of BIRDS) {
    const span = W + 24;
    const x = (((b.start + (t / 1000) * b.speed) % span) + span) % span - 12;
    const y = b.y + Math.sin(t * 0.0008 + b.phase) * 1.4;
    const up = Math.sin(t * 0.018 + b.phase) > 0;
    const px = Math.round(x);
    const py = Math.round(y);
    const wings: [number, number][] = up
      ? [
          [px - 1, py + 1],
          [px, py],
          [px + 1, py + 1],
        ]
      : [
          [px - 1, py],
          [px, py + 1],
          [px + 1, py],
        ];
    for (const [wx, wy] of wings) {
      if (wx < 0 || wy < 0 || wx >= W || wy >= H) continue;
      if (kinds[wy * W + wx] !== SKY) continue;
      blend(buf, wx, wy, PALETTE.bird, 0.8);
    }
  }
}

function shootingStar(buf: Uint8ClampedArray, kinds: Uint8Array, t: number): void {
  const CYCLE = 21000;
  const DURATION = 950;
  const p = t % CYCLE;
  if (p > DURATION) return;
  const k = p / DURATION;
  const headX = 4 + k * 44;
  const headY = 5 + k * 13;
  for (let i = 0; i < 10; i++) {
    const tail = 1 - i / 10;
    const x = Math.round(headX - i * 1.05);
    const y = Math.round(headY - i * 0.31);
    if (x < 0 || y < 0 || x >= W || y >= H) continue;
    if (kinds[y * W + x] !== SKY) continue;
    const fade = tail * (1 - k * 0.7) * (i === 0 ? 0.95 : 0.6);
    blend(buf, x, y, i === 0 ? PALETTE.moonHighlight : PALETTE.starWarm, fade);
  }
}

function drawFireflies(buf: Uint8ClampedArray, t: number): void {
  for (const f of FIREFLIES) {
    const x = f.x + Math.sin(t * 0.0006 * f.speed + f.phase) * 2.6;
    const y = f.y + Math.cos(t * 0.00072 * f.speed + f.phase * 1.3) * 1.7;
    const pulse = Math.max(0, Math.sin(t * 0.0013 * f.speed + f.phase));
    const alpha = 0.18 + pulse * pulse * 0.75;
    const px = Math.round(x);
    const py = Math.round(y);
    for (const [dx, dy] of [
      [0, 0],
      [1, 0],
      [-1, 0],
      [0, 1],
      [0, -1],
    ] as [number, number][]) {
      blend(buf, px + dx, py + dy, PALETTE.firefly, dx === 0 && dy === 0 ? alpha : alpha * 0.22);
    }
  }
}

function render(out: Uint8ClampedArray, base: Uint8ClampedArray, kinds: Uint8Array, t: number): void {
  out.set(base);

  // Stars twinkle; the ones near the horizon are dimmer so the sky stays grounded.
  for (const s of STARS) {
    if (kinds[s.y * W + s.x] !== SKY) continue;
    const twinkle = 0.5 + 0.5 * Math.sin(t * 0.0016 + s.phase);
    const height = 1 - s.y / 30;
    const alpha = (0.25 + 0.6 * twinkle) * (0.45 + height * 0.55);
    blend(out, s.x, s.y, s.warm ? PALETTE.starWarm : PALETTE.starCool, alpha);
  }

  // Sun: a slow 52 s drift with a small vertical bob.
  const sunA = (t / 52000) * Math.PI * 2;
  const sunX = 39 + Math.sin(sunA) * 5;
  const sunY = 25 + Math.cos(sunA) * 2;

  // Moon: on the other side of the sky, slower still (74 s).
  const moonA = (t / 74000) * Math.PI * 2 + Math.PI;
  const moonX = 15 + Math.sin(moonA) * 4;
  const moonY = 9 + Math.cos(moonA) * 1.6;

  // A small crescent: three pixels hugging the upper-left arc.
  const mx = Math.round(moonX);
  const my = Math.round(moonY);
  halo(out, kinds, moonX, moonY, 6, PALETTE.moonHalo, 0.12);
  blend(out, mx - 1, my, PALETTE.moon, 0.55);
  blend(out, mx, my - 1, PALETTE.moon, 0.6);
  blend(out, mx, my, PALETTE.moonHighlight, 0.85);
  blend(out, mx, my + 1, PALETTE.moon, 0.5);

  halo(out, kinds, sunX, sunY, 14, PALETTE.sunHalo, 0.22);
  halo(out, kinds, sunX, sunY, 8, PALETTE.sunOuter, 0.3);
  disc(out, kinds, sunX, sunY, 6, PALETTE.sunHalo, 0.92);
  disc(out, kinds, sunX, sunY, 4.2, PALETTE.sunOuter, 0.95);
  disc(out, kinds, sunX, sunY, 2.6, PALETTE.sunMid, 1);
  disc(out, kinds, sunX - 1, sunY - 1, 1.2, PALETTE.sunCore, 1);

  shootingStar(out, kinds, t);

  // Parallax cloud bands drift behind the ridges: higher bands move slower.
  for (const band of CLOUD_BANDS) {
    if (band.behindRidges) cloudBand(out, kinds, band, t);
  }

  birds(out, kinds, t);

  // Sun reflection: a widening, wobbling column on the water.
  for (let y = HORIZON; y < H; y++) {
    const depth = (y - HORIZON) / Math.max(1, H - HORIZON);
    const wobble = Math.sin(t * 0.0022 + y * 0.85) * (0.6 + depth * 1.8);
    const center = sunX + wobble;
    const half = 1.4 + depth * 4.8;
    for (let x = Math.floor(center - half); x <= Math.ceil(center + half); x++) {
      const sx = ((x % W) + W) % W;
      if (kinds[y * W + sx] !== WATER) continue;
      const edge = 1 - Math.abs(x - center) / half;
      if (edge <= 0) continue;
      const flicker = 0.55 + 0.45 * Math.sin(t * 0.005 + y * 1.7 + x * 0.6);
      const alpha = edge ** 1.4 * flicker * (1.05 - depth * 0.4);
      if (alpha <= 0.02) continue;
      blend(out, sx, y, depth < 0.35 ? PALETTE.reflectionNear : PALETTE.reflectionFar, alpha);
    }
  }

  drawFireflies(out, t);

  // Low mist scrolls in front of the peaks.
  for (const band of CLOUD_BANDS) {
    if (!band.behindRidges) cloudBand(out, kinds, band, t);
  }
}

let cachedBase: { pixels: Uint8ClampedArray; kinds: Uint8Array } | null = null;

/** One complete frame of the scene at time `t` (milliseconds). */
export function heroFrame(t: number): Uint8ClampedArray {
  cachedBase ??= buildBase();
  const frame = new Uint8ClampedArray(W * H * 4);
  render(frame, cachedBase.pixels, cachedBase.kinds, t);
  return frame;
}

export function HeroScene() {
  const ref = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const image = ctx.createImageData(W, H);

    const paint = (t: number) => {
      image.data.set(heroFrame(t));
      ctx.putImageData(image, 0, 0);
    };

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    if (reduce) {
      paint(14000);
      return;
    }

    let raf = 0;
    let lastDraw = -Infinity;
    const start = performance.now();
    let onScreen = true;

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (!onScreen || document.visibilityState === 'hidden') return;
      if (now - lastDraw < 1000 / FPS) return;
      lastDraw = now;
      paint(now - start);
    };
    paint(0);
    raf = requestAnimationFrame(tick);

    const observer =
      typeof IntersectionObserver !== 'undefined'
        ? new IntersectionObserver((entries) => {
            onScreen = entries.some((e) => e.isIntersecting);
          })
        : null;
    observer?.observe(canvas);

    return () => {
      cancelAnimationFrame(raf);
      observer?.disconnect();
    };
  }, []);

  return <canvas ref={ref} width={W} height={H} aria-label="Animated pixel-art dusk landscape" role="img" />;
}
